assert steps['training'][0]['loss']==steps['training_r2'][0]['loss'];assert [(s['samples_seen'],s['target_tokens_seen'],s['epoch']) for s in steps['training']]==[(s['samples_seen'],s['target_tokens_seen'],s['epoch']) for s in steps['training_r2']]
samples=[json.loads(l)['sample_id'] for l in (R/'data/datasets/rwkv_direct_read_summary_v1/train.jsonl').read_text().splitlines()];rng=random.Random(a['optimizer']['seed']);order=[]
