 w=csv.writer(f);w.writerow(['step','epoch','sample_id_from_registered_order','lr_0.01_loss','lr_0.0001_loss'])
 for i,(x,y,n) in enumerate(zip(steps['training'],steps['training_r2'],order),1):w.writerow([i,x['epoch'],n,x['loss'],y['loss']])
